component_data_script:
def norm(value):
	key = str(value or "").strip().lower()
	if key in ["you", "me", "personal", "people", "for you"]:
		return "personal"
	if key in ["business", "company", "companies", "for your business"]:
		return "business"
	return "both"


def tag_of(aud):
	if aud == "personal":
		return "For you"
	if aud == "business":
		return "For your business"
	return ""


def read_rows(raw):
	if isinstance(raw, str):
		try:
			raw = json.loads(raw)
		except Exception:
			raw = [line for line in raw.split("\n") if line.strip()]
	if not isinstance(raw, list):
		return []
	return [str(line) for line in raw if str(line).strip()]


def split_row(line, size):
	parts = [part.strip() for part in str(line).split("|")]
	while len(parts) < size:
		parts.append("")
	return parts

years = []
try:
	info = {}
	order = []
	for line in read_rows(props.get("years")):
		parts = split_row(line, 4)
		aud = norm(parts[0])
		if aud not in info:
			order.append(aud)
		info[aud] = {"span": parts[1], "filed_label": parts[2], "due_label": parts[3]}
	bars = {}
	for line in read_rows(props.get("bars")):
		parts = split_row(line, 5)
		if not parts[1]:
			continue
		aud = norm(parts[0])
		try:
			value = float(parts[2])
		except Exception:
			value = 0.0
		if value > 1:
			value = value / 100.0
		value = max(0.04, min(1.0, value))
		state = parts[3].strip().lower()
		if state not in ["done", "filed", "due", "ahead"]:
			state = "ahead"
		if aud not in bars:
			bars[aud] = []
		if aud not in info:
			order.append(aud)
			info[aud] = {"span": "", "filed_label": "", "due_label": ""}
		bars[aud].append({"month": parts[1], "height": str(int(value * 1000) / 10.0) + "%", "state": state, "label": parts[4]})
	months = {}
	for line in read_rows(props.get("months")):
		parts = split_row(line, 3)
		if not parts[1]:
			continue
		aud = norm(parts[0])
		if aud not in months:
			months[aud] = []
		months[aud].append({"name": parts[1], "line": parts[2]})
	for aud in order:
		item = info.get(aud) or {}
		years.append({
			"aud": aud,
			"tag": tag_of(aud),
			"span": item.get("span") or "",
			"filed_label": item.get("filed_label") or "",
			"due_label": item.get("due_label") or "",
			"bars": bars.get(aud) or [],
			"months": months.get(aud) or [],
		})
except Exception:
	years = []
component.years = years
